def look_and_say_sequence(start: str, n: int) -> str:
    if n == 1:
        return start

    current = start
    for _ in range(n - 1):
        next_element = []
        i = 0
        while i < len(current):
            count = 1
            while i + 1 < len(current) and current[i] == current[i + 1]:
                i += 1
                count += 1
            next_element.append(str(count) + current[i])
            i += 1
        current = ''.join(next_element)

    return current
